solution.python:
import base64
import json
import time

def _base64url_decode(s):
    s = s.replace('-', '+').replace('_', '/')
    padding = 4 - len(s) % 4
    if padding != 4:
        s += '=' * padding
    return base64.b64decode(s).decode('utf-8')

def decode_jwt(token: str) -> dict:
    try:
        parts = token.split('.')
        if len(parts) != 3:
            return None

        header = json.loads(_base64url_decode(parts[0]))
        payload = json.loads(_base64url_decode(parts[1]))

        return {'header': header, 'payload': payload}
    except Exception:
        return None

def is_expired(token: str) -> bool:
    decoded = decode_jwt(token)
    if not decoded:
        return True

    exp = decoded['payload'].get('exp')
    if exp is None:
        return False

    return time.time() > exp

def extract_claims(token: str) -> dict:
    decoded = decode_jwt(token)
    if not decoded:
        return {}

    standard_claims = ['iss', 'sub', 'aud', 'exp', 'iat', 'nbf', 'jti']
    payload = decoded['payload']
    return {k: payload[k] for k in standard_claims if k in payload}

solution.javascript:
function base64UrlDecode(str) {
  str = str.replace(/-/g, '+').replace(/_/g, '/');
  while (str.length % 4) str += '=';
  return JSON.parse(atob(str));
}

function decodeJWT(token) {
  try {
    const parts = token.split('.');
    if (parts.length !== 3) return null;
    const header = base64UrlDecode(parts[0]);
    const payload = base64UrlDecode(parts[1]);
    return { header, payload };
  } catch (e) {
    return null;
  }
}

function isExpired(token) {
  const decoded = decodeJWT(token);
  if (!decoded) return true;
  const exp = decoded.payload.exp;
  if (exp === undefined) return false;
  return Date.now() / 1000 > exp;
}

function extractClaims(token) {
  const decoded = decodeJWT(token);
  if (!decoded) return {};
  const standard = ['iss', 'sub', 'aud', 'exp', 'iat', 'nbf', 'jti'];
  const result = {};
  for (const key of standard) {
    if (key in decoded.payload) result[key] = decoded.payload[key];
  }
  return result;
}
